ALTER TABLE pipe_db_fvt2.t3 RENAME TO pipe_db_fvt2.t4;
select pg_sleep(2);

-- check send result
select name,table_name,status from [show pipes] where name like '%mock_2%';
-- -- code1 >20 total 1
select count(*) from defaultdb.mock_sink_to_db where topic = 'test_topic_mock11';
select count(*) from defaultdb.mock_sink_to_db where topic = 'test_topic_mock21' and kind = 'insert' and tb_name='t1';
select count(*) from defaultdb.mock_sink_to_db where topic = 'test_topic_mock21' and kind = 'insert' and tb_name='t3';

select * from defaultdb.mock_sink_to_db where topic = 'test_topic_mock20' and kind = 'insert' order by key;
select topic,kind,db_name,tb_name,data
from defaultdb.mock_sink_to_db where topic = 'test_topic_mock20' and kind != 'insert' order by key;

select * from defaultdb.mock_sink_to_db where topic = 'test_topic_mock21' and kind = 'insert' order by key;
select topic,kind,db_name,tb_name,data
from defaultdb.mock_sink_to_db where topic = 'test_topic_mock21' and kind != 'insert' order by key;

drop pipe test_pipe_mock_20;
drop pipe test_pipe_mock_21;

--create database pipe with history, only insert
create pipe test_pipe_mock_31 for database pipe_db_fvt2
       with options (enable='on',ignore_history='off',
       sink='mock://root@127.0.102.145:26257?topic_name=test_topic_mock31&mock_sink_to_db=defaultdb.mock_sink_to_db');
select name,table_name,status from [show pipes] where name like '%mock_3%';
-- restart pipe for unprocessed data
alter pipe test_pipe_mock_23 set low_watermark='2021-12-30 00:00:00';
alter pipe test_pipe_mock_23 set enable='on';

-- insert flight data begin history to start cdc.
--INSERT INTO pipe_db_fvt2.t1 (k_timestamp,id,e1,code1,code14,code8,code16),VALUES('2022-01-02 00:00:00',20,2,5,'2','1','2');

-- wait history process
select pg_sleep(4);
-- insert realtime data disorder
INSERT INTO pipe_db_fvt2.t1 (k_timestamp,id,e1,code1,code14,code8,code16),VALUES('2025-01-02 00:01:00',21,2,5,'2','1','2'),('2025-01-02 00:02:00',21,2,0,'2','1','2');
select pg_sleep(2);

-- check history and realtime result
-- insert 2 rows
select * from defaultdb.mock_sink_to_db where topic = 'test_topic_mock31' and kind = 'insert' order by key,tb_name;
-- snapshot 12 rows
select topic,kind,db_name,tb_name,data
from defaultdb.mock_sink_to_db where topic = 'test_topic_mock31' and kind != 'insert' order by key,tb_name;

select * from defaultdb.mock_sink_to_db where topic = 'test_topic_mock23' and kind  = 'insert'  order by key,tb_name;
select topic,kind,db_name,tb_name,data
from defaultdb.mock_sink_to_db where topic = 'test_topic_mock23' and kind != 'insert' order by key,tb_name;

DROP PIPE test_pipe_mock_23;
DROP PIPE test_pipe_mock_31;

select name,table_name,status from [show pipes];
select * from system.kwdb_unpush;
--check jobs
select * from [show jobs] where job_type='PIPE WATERMARK' and status='running';
-- -- cleanup
drop database if exists pipe_db_fvt2 cascade;
drop table defaultdb.mock_sink_to_db cascade;